284: function Resolve-ReplWorkspaceDirectory {
285:     # A marker-bearing current directory outranks the workspace env vars: ambient
286:     # MCP_WORKSPACE_PATH values leak across workspaces through host processes and
287:     # persistent consoles, and an inherited value must not re-bind marker trust,
288:     # API keys, and session logs to another workspace while the cache directory
289:     # stays local (triage-report-7c84e6437f7b42d0a67fbe32679a686a). This matches
290:     # the plugin hook's Get-PluginStartPath precedence.
291:     $providerLocation = $null
292:     try {
293:         $location = Get-Location
294:         if ($location.Provider.Name -eq 'FileSystem') {
295:             $providerLocation = $location.ProviderPath
296:         }
297:     } catch {
298:         # Fall through to the env and .NET current directory fallbacks.
299:     }
300: 
301:     # Only the PowerShell provider location is trusted for the marker check: the
302:     # process-wide [Environment]::CurrentDirectory can be stale in shared hosts.
303:     if (-not [string]::IsNullOrWhiteSpace($providerLocation) -and
304:         (Test-Path -LiteralPath $providerLocation -PathType Container)) {
305:         try {
306:             if ((Get-Command Find-MarkerFile -ErrorAction SilentlyContinue) -and
307:                 (Find-MarkerFile -StartDir $providerLocation)) {
308:                 return (Resolve-Path -LiteralPath $providerLocation).ProviderPath
309:             }
310:         } catch {
311:             # No marker above the current directory; consult the env fallbacks below.
312:         }
313:     }
314: 
315:     $candidates = @(
316:         $env:MCP_WORKSPACE_PATH,
317:         $env:MCPSERVER_WORKSPACE_PATH,
318:         $env:MCP_WORKSPACE_START_DIR,
319:         $env:CLAUDE_PROJECT_DIR,
320:         $providerLocation,
321:         [Environment]::CurrentDirectory
322:     )
323: 
324:     foreach ($candidate in $candidates) {
325:         if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
326:         if (Test-Path -LiteralPath $candidate -PathType Container) {
327:             return (Resolve-Path -LiteralPath $candidate).ProviderPath
328:         }
329:     }
