2328:     }
2329: 
2330:     $meta = Get-ReplSessionMeta
2331:     if (-not $meta) {
2332:         [Console]::Error.WriteLine("workflow.sessionlog.setTurnTitle requires cached session metadata. $(Get-ReplRecoveryGuidance)")
2333:         return $false
2334:     }
2335:     $reqId = Get-ReplTurnCacheField -Field 'turnRequestId'
2336:     if ([string]::IsNullOrWhiteSpace($reqId)) {
2337:         [Console]::Error.WriteLine('workflow.sessionlog.setTurnTitle requires an active turn requestId.')
2338:         return $false
2339:     }
2340: 
2341:     Set-ReplTurnCacheField -Field 'queryTitle' -Value $title | Out-Null
2342: 
2343:     $callParams = [ordered]@{
2344:         agent     = $meta.SourceType
2345:         sessionId = $meta.SessionId
2346:         requestId = $reqId
2347:         title     = $title
2348:     }
2349:     $callYaml = ConvertTo-Yaml -Data $callParams -Options WithIndentedSequences
2350:     $result = Invoke-ReplRaw -Method 'client.SessionLog.SetTurnTitleAsync' -ParamsYaml $callYaml
2351:     if (-not $result.Success) {
